<script setup lang="ts">
import { useLocale } from '../../locales';
const { translate } = useLocale();
import {ref,computed} from 'vue';import {Search,UsersRound,ArrowRight,Download} from 'lucide-vue-next';import WorkshopHeader from '../../components/WorkshopHeader.vue';import {customers} from '../../data/company';const search=ref('');const segment=ref('All customers');const segments=['All customers','Active','Dormant','High-value','Service due soon','Tyre customer','Open recommendations'];const shown=computed(()=>customers.filter(c=>(segment.value==='All customers'||c.segments.includes(segment.value))&&`${c.name} ${c.email} ${c.vehicles.join(' ')}`.toLowerCase().includes(search.value.toLowerCase())))
</script>
